import flowio, numpy as np, pandas as pd
def get_df(fname):
    fo = flowio.FlowData('/task/input/fcs/' + fname)
    events = np.reshape(fo.events, (-1, fo.channel_count))
    ch_names = [fo.channels[i]['pnn'] for i in range(1, fo.channel_count + 1)]
    return pd.DataFrame(events, columns=ch_names)

for sname, fcs in [('D617', 'PBMC_D617.fcs'), ('D685', 'PBMC_D685.fcs'), ('D858', 'PBMC_D858.fcs')]:
    df = get_df(fcs)
    if sname == 'D858':
        cells = df[df['FSC-A'] > 10000]
    else:
        cells = df[df['FSC-A'] > 35000]
    ratio = cells['FSC-A'] / cells['FSC-H']
    counts, bin_edges = np.histogram(ratio, bins=40, range=(1.0, 2.2))
    print(f"{sname} FSC-A/H ratio histogram:")
    for i in range(len(counts)):
        if counts[i] > 0 or (i > 0 and counts[i-1] > 0):
            print(f"{bin_edges[i]:.2f}-{bin_edges[i+1]:.2f}: {counts[i]}", end=' | ')
    print()
EOF
